/**  The host key differs from the one on record. Never offered for trust. */
"host_key_changed" | "host_key_revoked" | "auth_failed" | 
/**  The user declined a prompt or closed it. */
"cancelled" | "protocol_error" | 
/**  The saved hosts could not be read or written. */
"store_failed" | 
/**  The vault must be unlocked first. */
"vault_locked" | "wrong_password" | 
/**  A system service, such as the OS keychain, is missing. */
"unavailable" | "internal";

export type ExitFilterSpec = "any" | "success" | "failure";

export type FlowSpec = "none" | 
/**  XON/XOFF. */
"software" | 
/**  RTS/CTS. */
"hardware";

export type ForwardKindSpec = "local" | "remote" | "dynamic";

